		new SpringApplicationBuilder(GlobalPaymentServiceApplication.class, UnmigratedEntityScan.class)
				.web(WebApplicationType.NONE)
				.properties("spring.datasource.url=jdbc:h2:mem:validate-refuses-unmigrated-entity")
				.run()
				.close();
