				.exchange()
				.expectStatus().isOk()
				.expectBody()
				.jsonPath("$[0].balanceMinorUnits").isEqualTo(90_000L)
				.jsonPath("$[0].reservedAmountMinorUnits").isEqualTo(25_000L)
				.jsonPath("$[0].availableBalanceMinorUnits").isEqualTo(65_000L);
	}

