		client().get().uri(LISTING)
				.exchange()
				.expectStatus().isOk()
				.expectBody()
				.jsonPath("$[0].id").isEqualTo(1)
				.jsonPath("$[1].id").isEqualTo(2)
				.jsonPath("$[2].id").isEqualTo(3);
	}

